import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../../ui/overlays/dialog';
import { Button } from '../../ui/actions/button';
import { LoaderCircle, X, Check, AlertTriangle, Trash2 } from 'lucide-react';
import type React from 'react';
import { useState } from 'react';
import { cn } from '../../../lib/utils';

type Props = {
  id?: string;
  className?: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  content?: React.ReactNode;
  children?: React.ReactNode;
  onClose: () => void;
  onConfirm?: () => void | Promise<void>;
  showCancel?: boolean;
  cancelText?: React.ReactNode;
  confirmText?: React.ReactNode;
  confirmIcon?: React.ReactNode;
  variant?: 'default' | 'destructive' | 'success' | 'warning';
  hideFooter?: boolean;
  open?: boolean;
  disabled?: boolean;
  loading?: boolean;

  /**
   * @description The size of the dialog. Can be a string for custom sizes.
   * @example 'sm', 'md', 'lg', 'xl', 'fullscreen', '90%', '800px', '60vw'
   */
  size?: 'sm' | 'md' | 'lg' | 'xl' | 'fullscreen' | (string & {});
  extraFooter?: React.ReactNode;
};

export function BaseDialog({
  id,
  className,
  title,
  description,
  content,
  children,
  onClose,
  onConfirm,
  showCancel,
  cancelText,
  confirmText,
  confirmIcon,
  variant,
  hideFooter,
  open = true,
  disabled = false,
  loading,
  size = 'lg',
  extraFooter,
}: Props) {
  const [isLoading, setIsLoading] = useState(false);

  const handleConfirm = async () => {
    try {
      if (disabled || loading) return;
      if (onConfirm) {
        setIsLoading(true);
        await onConfirm();
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const isCustomSize = !['sm', 'md', 'lg', 'xl'].includes(size);

  const getSizeClasses = () => {
    if (size === 'fullscreen' || isCustomSize) {
      // For fullscreen, we'll use inline styles to override defaults
      return '';
    }

    const widthMap = {
      sm: 'sm:!max-w-sm',
      md: 'sm:!max-w-md',
      lg: 'sm:!max-w-lg',
      xl: 'sm:!max-w-xl',
    };
    return widthMap[size as keyof typeof widthMap];
  };

  const getSizeStyles = (): React.CSSProperties => {
    if (size === 'fullscreen') {
      return {
        width: '100vw',
        height: '100vh',
        maxWidth: '100vw',
        maxHeight: '100vh',
      };
    }

    if (isCustomSize) {
      return {
        width: size,
        maxWidth: size,
        maxHeight: '90vh',
      };
    }

    return {};
  };

  const getConfirmIcon = () => {
    if (isLoading) {
      return <LoaderCircle className="size-4 animate-spin" />;
    }

    if (confirmIcon) return confirmIcon;

    switch (variant) {
      case 'success':
        return <Check className="size-4" />;
      case 'destructive':
        return <Trash2 className="size-4" />;
      case 'warning':
        return <AlertTriangle className="size-4" />;
      default:
        return <Check className="size-4" />;
    }
  };

  const getButtonVariant = () => {
    if (variant === 'destructive') return 'destructive';
    if (variant === 'success') return 'default';
    if (variant === 'warning') return 'default';
    return 'default';
  };

  const getButtonClassName = () => {
    if (variant === 'success') {
      return 'bg-green-600 hover:bg-green-700 text-white shadow-sm hover:shadow-md transition-all dark:bg-green-400 dark:text-green-950 dark:hover:bg-green-500';
    }
    if (variant === 'warning') {
      return 'bg-amber-600 hover:bg-amber-700 text-white shadow-sm hover:shadow-md transition-all dark:bg-amber-400 dark:text-amber-950 dark:hover:bg-amber-500';
    }
    return '';
  };

  return (
    <Dialog key={id} open={open} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className={cn(getSizeClasses(), className ?? '')} style={getSizeStyles()}>
        {title && (
          <DialogHeader>
            <DialogTitle>{title}</DialogTitle>
            {description && <DialogDescription>{description}</DialogDescription>}
          </DialogHeader>
        )}
        {content} {children}
        {!hideFooter && (
          <DialogFooter>
            {extraFooter}

            {showCancel !== false && (
              <Button type="button" variant="outline" onClick={onClose}>
                <X className="size-4" />
                {cancelText ?? 'Cancel'}
              </Button>
            )}
            {onConfirm && (
              <Button
                type="button"
                variant={getButtonVariant()}
                className={getButtonClassName()}
                onClick={handleConfirm}
                disabled={disabled || loading || isLoading}
              >
                {isLoading || loading ? (
                  <LoaderCircle className="size-4 animate-spin" />
                ) : (
                  getConfirmIcon()
                )}
                {confirmText ?? 'Confirm'}
              </Button>
            )}
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
}

import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from '../../ui/overlays/sheet';
import { Button } from '../../ui/actions/button';
import type React from 'react';
import { cn } from '../../../lib/utils';
import { useState } from 'react';
import { LoaderCircle, XIcon, Maximize2, Minimize2 } from 'lucide-react';

type Props = {
  id?: string;
  className?: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  content?: React.ReactNode;
  children?: React.ReactNode;
  onClose: () => void;
  onConfirm?: () => void | Promise<void>;
  showCancel?: boolean;
  cancelText?: React.ReactNode;
  confirmText?: React.ReactNode;
  variant?: 'default' | 'destructive' | 'success' | 'warning';
  hideFooter?: boolean;
  open?: boolean;
  direction?: 'top' | 'bottom' | 'left' | 'right';
  disabled?: boolean;
  loading?: boolean;
  /**
   * @description The size of the drawer. Can be a string for custom sizes.
   * @example 'sm', 'md', 'lg', 'xl', 'fullscreen', '90%', '800px', '60vw'
   */
  size?: 'sm' | 'md' | 'lg' | 'xl' | 'fullscreen' | (string & {});
  showFullscreenToggle?: boolean;
  /**
   * Merged onto the main body wrapper (below the header, above the footer).
   * Use to change overflow (e.g. nested column scrolling) while keeping flex-growth.
   */
  contentContainerClassName?: string;
};

export function BaseDrawer({
  id,
  className,
  title,
  description,
  content,
  children,
  onClose,
  onConfirm,
  showCancel,
  cancelText,
  confirmText,
  variant,
  hideFooter,
  open = true,
  direction = 'right',
  disabled = false,
  loading,
  size = 'lg',
  showFullscreenToggle = true,
  contentContainerClassName,
}: Props) {
  const [isLoading, setIsLoading] = useState(false);
  const [currentSize, setCurrentSize] = useState(size);
  const [previousSize, setPreviousSize] = useState<Exclude<typeof size, 'fullscreen'>>('md');

  const handleConfirm = async () => {
    try {
      if (disabled || loading) return;
      if (onConfirm) {
        setIsLoading(true);
        await onConfirm();
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggleFullscreen = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (currentSize === 'fullscreen') {
      setCurrentSize(previousSize);
    } else {
      setPreviousSize(currentSize as Exclude<typeof currentSize, 'fullscreen'>);
      setCurrentSize('fullscreen');
    }
  };

  const isCustomSize = !['sm', 'md', 'lg', 'xl', 'fullscreen'].includes(currentSize);

  const getSizeClasses = () => {
    if (currentSize === 'fullscreen' || isCustomSize) {
      return '';
    }

    const isHorizontal = direction === 'left' || direction === 'right';

    if (isHorizontal) {
      const widthMap = {
        sm: 'sm:!max-w-sm',
        md: 'sm:!max-w-md',
        lg: 'sm:!max-w-lg',
        xl: 'sm:!max-w-xl',
      };
      return widthMap[currentSize as keyof typeof widthMap];
    }

    const heightMap = {
      sm: '!max-h-[50vh]',
      md: '!max-h-[70vh]',
      lg: '!max-h-[80vh]',
      xl: '!max-h-[90vh]',
    };
    return heightMap[currentSize as keyof typeof heightMap];
  };

  const getSizeStyles = (): React.CSSProperties => {
    if (currentSize === 'fullscreen') {
      const isHorizontal = direction === 'left' || direction === 'right';
      if (isHorizontal) {
        return { width: '100%', maxWidth: '100%' };
      }
      return { maxHeight: '100vh', height: '100vh' };
    }

    if (isCustomSize) {
      const isHorizontal = direction === 'left' || direction === 'right';
      if (isHorizontal) {
        return { width: currentSize, maxWidth: currentSize };
      }
      return { height: currentSize, maxHeight: currentSize };
    }

    return {};
  };

  return (
    <Sheet key={id} open={open} onOpenChange={(isOpen) => !isOpen && onClose()}>
      <SheetContent
        side={direction}
        showCloseButton={false}
        className={cn('flex flex-col gap-0', getSizeClasses(), className)}
        style={getSizeStyles()}
      >
        {title && (
          <SheetHeader className="flex flex-row items-center justify-between">
            <SheetTitle>{title}</SheetTitle>
            <div className="flex items-center gap-2">
              {showFullscreenToggle && (
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={handleToggleFullscreen}
                  disabled={loading}
                  aria-label={currentSize === 'fullscreen' ? 'Exit fullscreen' : 'Enter fullscreen'}
                >
                  {currentSize === 'fullscreen' ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
                </Button>
              )}
              <SheetClose
                render={
                  <Button variant="ghost" size="icon" disabled={loading}>
                    <XIcon size={20} />
                  </Button>
                }
              />
            </div>
          </SheetHeader>
        )}
        <div
          className={cn(
            'flex min-h-0 flex-1 flex-col overflow-y-auto px-4 pb-9',
            contentContainerClassName
          )}
        >
          {description && <SheetDescription render={<div />}>{description}</SheetDescription>}
          {content}
          {children}
        </div>
        {!hideFooter && (
          <SheetFooter className="mt-auto flex flex-row items-center justify-end gap-2 border-t bg-background">
            {showCancel !== false && (
              <SheetClose
                render={
                  <Button variant="ghost" disabled={loading}>
                    {cancelText ?? 'Close'}
                  </Button>
                }
              />
            )}
            {onConfirm && (
              <Button
                variant={variant === 'destructive' ? 'destructive' : 'default'}
                onClick={handleConfirm}
                disabled={disabled || loading}
              >
                {isLoading && <LoaderCircle className="size-4 animate-spin" />}
                {confirmText ?? 'Confirm'}
              </Button>
            )}
          </SheetFooter>
        )}
      </SheetContent>
    </Sheet>
  );
}

import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '../../ui/overlays/alert-dialog';
import { Button } from '../../ui/actions/button';
import { cn } from '../../../lib/utils';
import type React from 'react';
import { useState } from 'react';
import { LoaderCircle } from 'lucide-react';

type ConfirmDialogProps = {
  id?: string;
  className?: string;
  title?: React.ReactNode;
  description?: string | React.ReactNode;
  content?: React.ReactNode;
  onClose?: () => void;
  onConfirm?: () => void | Promise<void>;
  showCancel?: boolean;
  cancelText?: React.ReactNode;
  confirmText?: React.ReactNode;
  variant?: 'default' | 'destructive' | 'success' | 'warning';
  hideFooter?: boolean;
  open?: boolean;
  disabled?: boolean;
  loading?: boolean;
  children?: React.ReactNode;
  /**
   * @deprecated Use onClose instead
   */
  onOpenChange?: (open: boolean) => void;
};

export function ConfirmDialog({
  id,
  className,
  title,
  description,
  content,
  onClose,
  onConfirm,
  showCancel,
  cancelText,
  confirmText,
  variant,
  hideFooter,
  open = true,
  disabled = false,
  loading,
  children,
  onOpenChange,
}: ConfirmDialogProps) {
  const [isLoading, setIsLoading] = useState(false);

  const handleConfirm = async () => {
    try {
      if (disabled || loading) return;
      if (onConfirm) {
        setIsLoading(true);
        await onConfirm();
      }
      onClose?.();
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AlertDialog
      key={id}
      open={open}
      onOpenChange={(open) => {
        if (onOpenChange) {
          onOpenChange(open);
        } else {
          !open && onClose?.();
        }
      }}
    >
      <AlertDialogContent className={cn(className ?? '')}>
        {title && (
          <AlertDialogHeader className="text-start">
            <AlertDialogTitle>{title}</AlertDialogTitle>
            {description && (
              <AlertDialogDescription asChild>
                <div>{description}</div>
              </AlertDialogDescription>
            )}
          </AlertDialogHeader>
        )}
        {content}
        {children}
        {!hideFooter && (
          <AlertDialogFooter>
            {showCancel !== false && (
              <AlertDialogCancel disabled={loading} onClick={onClose}>
                {cancelText ?? 'Cancel'}
              </AlertDialogCancel>
            )}
            {onConfirm && (
              <Button
                variant={variant === 'destructive' ? 'destructive' : 'default'}
                onClick={handleConfirm}
                disabled={disabled || loading}
              >
                {isLoading && <LoaderCircle className="size-4 animate-spin" />}
                {confirmText ?? 'Confirm'}
              </Button>
            )}
          </AlertDialogFooter>
        )}
      </AlertDialogContent>
    </AlertDialog>
  );
}

import { ConfirmDialog } from './confirm-dialog';
import { BaseDialog } from './base-dialog';
import { BaseDrawer } from './base-drawer';
import { useModals } from '../../../context/modal-provider/useModals';

export function GlobalModal() {
  const { modals, closeModal } = useModals();

  return (
    <>
      {Object.entries(modals).map(([id, config]) => {
        const handleClose = () => {
          config.onClose?.();
          closeModal(id);
        };

        const handleConfirm = async () => {
          if (config.onConfirm) {
            await config.onConfirm();
          }
          closeModal(id);
        };

        if (config.type === 'confirm') {
          return (
            <ConfirmDialog
              key={id}
              id={id}
              open={true}
              onClose={handleClose}
              onConfirm={handleConfirm}
              title={config.title}
              description={config.description}
              content={config.content}
              confirmText={config.confirmText}
              cancelText={config.cancelText}
              variant={config.variant}
              className={config.className}
              showCancel={config.showCancel}
            />
          );
        }

        if (config.type === 'custom') {
          const Component = config.component;
          return (
            <Component
              key={id}
              {...config.componentProps}
              onClose={handleClose}
              onConfirm={config.onConfirm ? handleConfirm : undefined}
            />
          );
        }

        // inner-content type
        const isDrawer = config.style === 'drawer';
        const direction = config.direction ?? 'right';

        if (config.type === 'inner-content') {
          if (isDrawer) {
            return (
              <BaseDrawer
                key={id}
                id={id}
                className={config.className}
                title={config.title}
                description={config.description}
                content={config.content}
                onClose={handleClose}
                onConfirm={config.onConfirm ? handleConfirm : undefined}
                showCancel={config.showCancel}
                cancelText={config.cancelText}
                confirmText={config.confirmText}
                variant={config.variant}
                open={true}
                direction={direction}
              />
            );
          }

          return (
            <BaseDialog
              key={id}
              id={id}
              className={config.className}
              title={config.title}
              description={config.description}
              content={config.content}
              onClose={handleClose}
              onConfirm={config.onConfirm ? handleConfirm : undefined}
              showCancel={config.showCancel}
              cancelText={config.cancelText}
              confirmText={config.confirmText}
              variant={config.variant}
              open={true}
            />
          );
        }

        return null;
      })}
    </>
  );
}

export * from './base-dialog';
export * from './base-drawer';
export * from './confirm-dialog';
export * from './global-modal';
